/* Authoring batch 08 — communication, digital life, administration, transport,
 * health, food, household equipment, geography, weather and community.
 * Examples are individually contextualised; all content remains draft.
 */
(() => {
  const makeSense = (id, definition, definitionEn, definitionZh, examples) => ({
    id, definition, definitionEn, definitionZh,
    translationStatus:{en:"machine_assisted_draft",zh:"machine_assisted_draft"}, examples
  });
  const makeEntry = (slug, word, part, definition, definitionEn, definitionZh, examples, categories) => {
    const id = "ms.dict." + slug;
    return {
      id, schemaVersion:1, languageCode:"ms", contentVersion:"u3-ms-dict-0.8.0",
      word, part, definition, definitionEn, definitionZh, examples, related:[],
      categories, searchForms:[],
      morphology:{type:"kata dasar atau frasa leksikal",forms:[],notes:"Tiada bentuk terbitan ditambah sebagai alias carian dalam batch ini; bentuk carian memerlukan semakan leksikal khusus."},
      senses:[makeSense(id+".s1",definition,definitionEn,definitionZh,examples)],
      provenance:{authoringMethod:"original-authored",sourcesConsulted:[],sourceTextCopied:false,
        authoringNote:"Original draft; no external lexical text imported; source verification and human review pending.",
        licenceStatus:"original-draft-rights-review-pending",editorialStatus:"draft",reviewerId:null}
    };
  };
  window.SWIFT_MALAY_DICTIONARY.push(
    makeEntry("berita","berita","kata nama","Maklumat tentang peristiwa atau perkara semasa yang disampaikan kepada orang ramai.","News; information about current events shared with the public.","新闻；向公众传达的时事信息。",["Saya membaca berita tempatan sebelum pergi bekerja."],["komunikasi"]),
    makeEntry("akhbar","akhbar","kata nama","Penerbitan berkala yang memuatkan berita, rencana dan iklan.","Newspaper; a periodical containing news, articles and advertisements.","报纸；刊载新闻、文章和广告的定期出版物。",["Ayah membeli akhbar di kedai berhampiran stesen bas."],["komunikasi"]),
    makeEntry("majalah","majalah","kata nama","Penerbitan berkala yang mengandungi rencana, gambar dan bahan bacaan khusus.","Magazine; a periodical with articles, pictures and specialised reading material.","杂志；刊载文章、图片和专题读物的定期出版物。",["Kakak melanggan majalah tentang seni reka."],["komunikasi"]),
    makeEntry("siaran","siaran","kata nama","Penyampaian maklumat atau rancangan melalui radio, televisyen atau rangkaian.","Broadcast; transmission of information or programmes by radio, television or a network.","广播；通过电台、电视或网络传送信息或节目。",["Siaran berita bermula pada pukul lapan malam."],["komunikasi"]),
    makeEntry("pengumuman","pengumuman","kata nama","Pemberitahuan rasmi tentang sesuatu perkara kepada orang ramai atau kumpulan tertentu.","Announcement; an official notice made to the public or a particular group.","公告；向公众或特定群体正式通知某事。",["Pengumuman perubahan jadual ditampal pada papan kenyataan."],["komunikasi"]),
    makeEntry("mesej","mesej","kata nama","Maklumat ringkas yang disampaikan secara lisan, bertulis atau elektronik.","Message; information conveyed verbally, in writing or electronically.","信息；通过口头、书面或电子方式传达的内容。",["Saya meninggalkan mesej kepada rakan sekerja."],["komunikasi"]),
    makeEntry("panggilan","panggilan","kata nama","Hubungan komunikasi melalui telefon atau tindakan memanggil seseorang.","Call; a telephone communication or the act of calling someone.","通话；电话联系或呼叫某人的行为。",["Saya terlepas panggilan daripada nombor pejabat."],["komunikasi"]),
    makeEntry("telefon-bimbit","telefon bimbit","kata nama","Telefon mudah alih yang boleh dibawa dan digunakan di pelbagai tempat.","Mobile phone; a portable telephone used in different places.","手机；可随身携带并在不同地点使用的电话。",["Telefon bimbit saya kehabisan bateri ketika dalam perjalanan."],["teknologi"]),
    makeEntry("papan-kekunci","papan kekunci","kata nama","Peranti input yang mempunyai kekunci untuk memasukkan huruf, nombor dan arahan.","Keyboard; an input device with keys for entering letters, numbers and commands.","键盘；带有按键、用于输入字母、数字和指令的设备。",["Beberapa kekunci pada papan kekunci itu tidak berfungsi."],["teknologi"]),
    makeEntry("tetikus","tetikus","kata nama","Peranti penunjuk yang mengawal gerakan kursor pada skrin komputer.","Computer mouse; a pointing device that controls a computer cursor.","鼠标；控制电脑光标移动的指向设备。",["Tetikus tanpa wayar itu perlu dicas semula."],["teknologi"]),
    makeEntry("skrin","skrin","kata nama","Permukaan paparan yang menunjukkan imej, teks atau maklumat elektronik.","Screen; a display surface showing images, text or electronic information.","屏幕；显示图像、文字或电子信息的表面。",["Retakan kecil muncul pada skrin telefon saya."],["teknologi"]),
    makeEntry("pencetak","pencetak","kata nama","Mesin yang menghasilkan salinan teks atau imej pada kertas.","Printer; a machine that produces copies of text or images on paper.","打印机；将文字或图像印到纸上的机器。",["Pencetak pejabat kehabisan dakwat hitam."],["teknologi"]),
    makeEntry("fail","fail","kata nama","Himpunan dokumen atau rekod yang disimpan bersama dalam bentuk fizikal atau digital.","File; a collection of documents or records stored together physically or digitally.","文件；集中存放的纸本或数码文档或记录。",["Simpan fail itu dalam folder projek yang betul."],["pentadbiran"]),
    makeEntry("folder","folder","kata nama","Tempat atau direktori untuk mengumpulkan dan menyusun fail.","Folder; a place or directory for grouping and organising files.","文件夹；用于归类和整理文件的实体夹或目录。",["Saya mencipta folder berasingan untuk setiap mata pelajaran."],["teknologi"]),
    makeEntry("kata-laluan","kata laluan","kata nama","Gabungan aksara rahsia yang digunakan untuk mengesahkan identiti atau membuka akses.","Password; a secret combination of characters used to verify identity or grant access.","密码；用于验证身份或取得访问权限的秘密字符组合。",["Gunakan kata laluan yang sukar diteka."],["teknologi"]),
    makeEntry("laman-web","laman web","kata nama","Himpunan halaman digital yang boleh dicapai melalui rangkaian internet.","Website; a collection of digital pages accessible through the internet.","网站；可通过互联网访问的一组数码页面。",["Laman web sekolah memaparkan kalendar akademik."],["teknologi"]),
    makeEntry("pautan","pautan","kata nama","Unsur yang menghubungkan satu halaman atau sumber digital dengan sumber lain.","Link; an element connecting one digital page or resource to another.","链接；连接不同数码页面或资源的元素。",["Klik pautan dalam e-mel untuk membuka halaman pendaftaran."],["teknologi"]),
    makeEntry("rangkaian","rangkaian","kata nama","Sistem hubungan antara beberapa peranti, tempat atau pihak untuk berkongsi maklumat.","Network; a system connecting devices, places or parties to share information.","网络；连接多个设备、地点或单位以共享信息的系统。",["Rangkaian pejabat terganggu selepas bekalan elektrik terputus."],["teknologi"]),
    makeEntry("isyarat","isyarat","kata nama","Tanda atau petunjuk yang menyampaikan maklumat atau arahan.","Signal; a sign or indication that conveys information or an instruction.","信号；传达信息或指示的标志或提示。",["Isyarat telefon lemah di dalam bangunan itu."],["komunikasi"]),
    makeEntry("arahan","arahan","kata nama","Panduan atau perintah tentang perkara yang perlu dilakukan.","Instruction; guidance or an order about what should be done.","指示；关于应执行事项的指导或命令。",["Baca arahan pada label sebelum menggunakan bahan pencuci."],["pendidikan"]),
    makeEntry("permohonan","permohonan","kata nama","Permintaan rasmi untuk mendapatkan kelulusan, kemudahan atau pertimbangan.","Application; a formal request for approval, a facility or consideration.","申请；正式请求批准、提供便利或予以考虑。",["Permohonan biasiswa perlu dihantar sebelum bulan Jun."],["pentadbiran"]),
    makeEntry("kelulusan","kelulusan","kata nama","Kebenaran atau persetujuan rasmi yang diberikan oleh pihak berkuasa atau pihak berkaitan.","Approval; official permission or agreement granted by an authority.","批准；由主管或相关单位给予的正式许可或同意。",["Projek itu hanya bermula selepas kelulusan diperoleh."],["pentadbiran"]),
    makeEntry("aduan","aduan","kata nama","Pernyataan tentang masalah atau layanan yang dianggap tidak memuaskan.","Complaint; a statement about a problem or unsatisfactory treatment.","投诉；针对问题或不满意待遇提出的陈述。",["Penduduk membuat aduan tentang lampu jalan yang rosak."],["pentadbiran"]),
    makeEntry("maklum-balas","maklum balas","kata nama","Respons atau pandangan yang diberikan terhadap sesuatu tindakan, hasil atau cadangan.","Feedback; a response or opinion about an action, result or proposal.","反馈；针对行动、成果或建议提出的回应或意见。",["Pensyarah memberikan maklum balas terhadap draf esei saya."],["pendidikan"]),
    makeEntry("perbincangan","perbincangan","kata nama","Pertukaran pendapat untuk memahami atau menyelesaikan sesuatu perkara.","Discussion; an exchange of views to understand or resolve a matter.","讨论；交换意见以理解或解决某事。",["Perbincangan kumpulan membantu kami memilih tajuk projek."],["komunikasi"]),
    makeEntry("jadual","jadual","kata nama","Senarai yang menyusun masa atau urutan sesuatu aktiviti.","Schedule or timetable; a list arranging the time or order of activities.","时间表；安排活动时间或次序的清单。",["Jadual peperiksaan dipaparkan di laman web kolej."],["pendidikan"]),
    makeEntry("tarikh-akhir","tarikh akhir","kata nama","Hari atau masa terakhir sesuatu tugasan perlu diselesaikan.","Deadline; the final date or time by which a task must be completed.","截止日期；必须完成任务的最后日期或时间。",["Hantar laporan sebelum tarikh akhir pada hari Jumaat."],["pendidikan"]),
    makeEntry("pengesahan","pengesahan","kata nama","Tindakan memastikan bahawa sesuatu maklumat atau perkara adalah benar atau sah.","Confirmation or verification; establishing that information or a matter is true or valid.","确认；核实某项信息或事项真实有效的行为。",["Pengesahan pembayaran dihantar selepas transaksi berjaya."],["pentadbiran"]),
    makeEntry("bukti","bukti","kata nama","Maklumat atau keterangan yang menyokong sesuatu dakwaan atau kesimpulan.","Evidence or proof; information supporting a claim or conclusion.","证据；支持某项主张或结论的信息或说明。",["Resit itu menjadi bukti bahawa bayaran telah dibuat."],["pentadbiran"]),
    makeEntry("salinan","salinan","kata nama","Hasil pendua sesuatu dokumen, gambar atau bahan lain.","Copy; a duplicate of a document, image or other material.","副本；文件、图像或其他材料的复制件。",["Simpan satu salinan resit untuk rujukan."],["pentadbiran"]),
    makeEntry("wang-tunai","wang tunai","kata nama","Wang dalam bentuk fizikal seperti wang kertas dan syiling.","Cash; money in physical forms such as banknotes and coins.","现金；纸币和硬币等实体货币。",["Kedai kecil itu hanya menerima wang tunai."],["perniagaan"]),
    makeEntry("syiling","syiling","kata nama","Wang logam yang mempunyai nilai tertentu.","Coin; a metal piece of money with a particular value.","硬币；具有特定面值的金属货币。",["Saya menggunakan syiling untuk membeli air di mesin layan diri."],["perniagaan"]),
    makeEntry("baki","baki","kata nama","Jumlah yang masih tinggal selepas sebahagian digunakan, dibayar atau ditolak.","Balance or remainder; an amount left after use, payment or deduction.","余额；使用、付款或扣除后剩余的数额。",["Semak baki akaun sebelum membuat pemindahan wang."],["perniagaan"]),
    makeEntry("diskaun","diskaun","kata nama","Pengurangan daripada harga asal sesuatu barang atau perkhidmatan.","Discount; a reduction from the original price of goods or services.","折扣；从商品或服务原价中扣除的金额。",["Kedai itu menawarkan diskaun untuk pembelian dalam talian."],["perniagaan"]),
    makeEntry("pembekal","pembekal","kata nama","Pihak yang membekalkan barang atau perkhidmatan kepada individu atau organisasi.","Supplier; a party that provides goods or services to a person or organisation.","供应商；向个人或机构提供商品或服务的一方。",["Pembekal menghantar bahan mentah pada awal pagi."],["perniagaan"]),
    makeEntry("pesanan","pesanan","kata nama","Permintaan untuk menyediakan atau menghantar barang atau perkhidmatan.","Order; a request for goods or services to be prepared or delivered.","订单；要求准备或交付商品或服务的请求。",["Semak alamat penghantaran sebelum mengesahkan pesanan."],["perniagaan"]),
    makeEntry("penghantaran","penghantaran","kata nama","Proses membawa atau menyerahkan barang, dokumen atau orang ke destinasi.","Delivery or dispatch; taking goods, documents or people to a destination.","运送；将商品、文件或人员送达目的地的过程。",["Penghantaran bungkusan dijangka tiba esok."],["perniagaan"]),
    makeEntry("bungkusan","bungkusan","kata nama","Barang yang dibalut atau dimasukkan ke dalam bekas untuk dibawa atau dihantar.","Parcel or package; an item wrapped or placed in a container for transport.","包裹；为携带或寄送而包装或装入容器的物品。",["Saya menulis alamat penerima pada bungkusan sebelum ke pejabat pos."],["perniagaan"]),
    makeEntry("kaunter","kaunter","kata nama","Meja atau tempat khusus untuk urusan perkhidmatan, pertanyaan atau pembayaran.","Counter; a designated desk or place for service, enquiries or payment.","柜台；办理服务、查询或付款事务的指定地点。",["Ambil nombor giliran di kaunter pendaftaran."],["perkhidmatan"]),
    makeEntry("giliran","giliran","kata nama","Urutan atau masa seseorang mendapat peluang untuk melakukan sesuatu.","Turn or queue order; the sequence in which someone gets an opportunity.","轮候次序；某人获得机会或服务的先后顺序。",["Sila tunggu giliran sebelum berjumpa doktor."],["perkhidmatan"]),
    makeEntry("barisan","barisan","kata nama","Susunan orang atau benda yang berada dalam satu garis atau urutan.","Queue or row; people or things arranged in a line or sequence.","队伍；排成一列或按顺序排列的人或物。",["Barisan penumpang bergerak perlahan di pintu masuk."],["kehidupan harian"]),
    makeEntry("pintu-masuk","pintu masuk","kata nama","Tempat atau bukaan yang digunakan untuk memasuki bangunan atau kawasan.","Entrance; a place or opening used to enter a building or area.","入口；用于进入建筑物或区域的地点或开口。",["Pengunjung menunjukkan tiket di pintu masuk."],["tempat"]),
    makeEntry("pintu-keluar","pintu keluar","kata nama","Tempat atau bukaan yang digunakan untuk meninggalkan bangunan atau kawasan.","Exit; a place or opening used to leave a building or area.","出口；用于离开建筑物或区域的地点或开口。",["Ikut tanda arah ke pintu keluar kecemasan."],["tempat"]),
    makeEntry("tempat-letak-kereta","tempat letak kereta","kata nama","Kawasan yang disediakan untuk meletakkan kenderaan apabila tidak digunakan.","Car park; an area provided for parking vehicles when not in use.","停车场；供车辆停放的区域。",["Tempat letak kereta pusat beli-belah itu penuh pada hujung minggu."],["pengangkutan"]),
    makeEntry("stesen-minyak","stesen minyak","kata nama","Premis yang menjual bahan api dan biasanya menyediakan kemudahan berkaitan kenderaan.","Petrol station; premises selling fuel and usually offering vehicle-related facilities.","加油站；销售燃料并通常提供车辆相关设施的场所。",["Kami berhenti di stesen minyak untuk mengisi petrol."],["pengangkutan"]),
    makeEntry("tayar","tayar","kata nama","Bahagian getah berbentuk gelang yang dipasang pada roda kenderaan.","Tyre; a ring-shaped rubber part fitted around a vehicle wheel.","轮胎；安装在车辆车轮上的环形橡胶部件。",["Periksa tekanan tayar sebelum perjalanan jauh."],["pengangkutan"]),
    makeEntry("brek","brek","kata nama","Mekanisme yang digunakan untuk memperlahankan atau menghentikan pergerakan kenderaan.","Brake; a mechanism used to slow down or stop a vehicle.","刹车；用于减慢或停止车辆移动的装置。",["Mekanik memeriksa brek sebelum kereta diserahkan kepada pemilik."],["pengangkutan"]),
    makeEntry("enjin","enjin","kata nama","Mesin yang menukarkan tenaga kepada gerakan atau kuasa untuk mengendalikan sesuatu.","Engine; a machine that converts energy into motion or power.","发动机；将能量转化为运动或动力的机器。",["Pemandu mematikan enjin ketika menunggu penumpang."],["pengangkutan"]),
    makeEntry("minyak-enjin","minyak enjin","kata nama","Cecair pelincir yang mengurangkan geseran dan membantu melindungi bahagian enjin.","Engine oil; a lubricant that reduces friction and protects engine parts.","发动机机油；减少摩擦并保护发动机部件的润滑液。",["Mekanik menukar minyak enjin mengikut jadual penyelenggaraan."],["pengangkutan"]),
    makeEntry("lampu-isyarat","lampu isyarat","kata nama","Peranti lampu yang mengawal pergerakan kenderaan dan pejalan kaki di persimpangan.","Traffic light; a light device controlling vehicles and pedestrians at junctions.","交通灯；在路口控制车辆和行人通行的灯号装置。",["Pemandu berhenti apabila lampu isyarat bertukar merah."],["pengangkutan"]),
    makeEntry("lintasan-pejalan-kaki","lintasan pejalan kaki","kata nama","Bahagian jalan yang ditandakan untuk membolehkan pejalan kaki melintas dengan lebih selamat.","Pedestrian crossing; a marked road area for safer pedestrian crossing.","行人过道；道路上供行人较安全横过的标示区域。",["Murid melintas melalui lintasan pejalan kaki di hadapan sekolah."],["pengangkutan"]),
    makeEntry("jejantas","jejantas","kata nama","Laluan bertingkat yang membolehkan pejalan kaki melintasi jalan atau halangan.","Footbridge; an elevated route for crossing a road or obstacle.","行人天桥；让行人跨越道路或障碍物的高架通道。",["Murid menggunakan jejantas untuk menyeberangi jalan yang sibuk."],["pengangkutan"]),
    makeEntry("landasan","landasan","kata nama","Laluan khusus yang dibina untuk pergerakan kereta api atau pesawat.","Track or runway; a dedicated route for trains or aircraft.","轨道；跑道；供列车或飞机使用的专用路线。",["Kereta api berhenti apabila landasan di hadapan ditutup."],["pengangkutan"]),
    makeEntry("gerabak","gerabak","kata nama","Bahagian kereta api yang membawa penumpang atau barang.","Railway carriage or wagon; a train vehicle carrying passengers or goods.","火车车厢；列车上运载乘客或货物的部分。",["Pekerja memeriksa gerabak sebelum perjalanan bermula."],["pengangkutan"]),
    makeEntry("tambang","tambang","kata nama","Bayaran untuk menggunakan pengangkutan atau mendapatkan perkhidmatan perjalanan.","Fare; the amount paid for transport or a journey service.","车费；使用交通工具或乘搭旅程服务所支付的费用。",["Tambang bas ekspres meningkat pada musim perayaan."],["pengangkutan"]),
    makeEntry("penumpang","penumpang","kata nama","Orang yang menaiki kenderaan tetapi bukan pemandunya.","Passenger; a person travelling in a vehicle who is not its driver.","乘客；乘坐交通工具但不是驾驶者的人。",["Semua penumpang diminta memakai tali pinggang keledar."],["pengangkutan"]),
    makeEntry("pemandu","pemandu","kata nama","Orang yang mengendalikan kenderaan atau mengarahkan pergerakannya.","Driver; a person who operates or guides a vehicle.","司机；操作或驾驶交通工具的人。",["Setiap pemandu perlu mematuhi had laju."],["pengangkutan"]),
    makeEntry("pejalan-kaki","pejalan kaki","kata nama","Orang yang bergerak dari satu tempat ke tempat lain dengan berjalan.","Pedestrian; a person travelling on foot.","行人；以步行方式从一处前往另一处的人。",["Pemandu perlu memberi laluan kepada pejalan kaki."],["pengangkutan"]),
    makeEntry("persimpangan","persimpangan","kata nama","Tempat dua atau lebih jalan atau laluan bertemu atau bersilang.","Intersection or junction; a place where roads or routes meet.","交叉路口；两条或多条道路或路线交会的地点。",["Kesesakan berlaku di persimpangan utama pada waktu pulang kerja."],["pengangkutan"]),
    makeEntry("kejohanan","kejohanan","kata nama","Pertandingan yang melibatkan beberapa peserta atau pasukan untuk menentukan pemenang.","Championship or tournament; a competition involving participants or teams.","锦标赛；由多个参赛者或队伍参与以决出胜者的比赛。",["Kejohanan badminton sekolah bermula minggu hadapan."],["sukan"]),
    makeEntry("peserta","peserta","kata nama","Orang yang mengambil bahagian dalam sesuatu kegiatan atau pertandingan.","Participant; a person taking part in an activity or competition.","参与者；参加某项活动或比赛的人。",["Setiap peserta mendaftar sebelum bengkel bermula."],["masyarakat"]),
    makeEntry("pengadil","pengadil","kata nama","Orang yang mengawasi pertandingan dan memastikan peraturan dipatuhi.","Referee or judge; a person who oversees a competition and enforces its rules.","裁判；监督比赛并确保遵守规则的人。",["Pengadil meniup wisel apabila pemain melakukan kesalahan."],["sukan"]),
    makeEntry("kecergasan","kecergasan","kata nama","Keadaan tubuh yang sihat dan mampu melakukan aktiviti fizikal dengan baik.","Fitness; a healthy physical condition enabling effective activity.","体能；身体健康并能良好进行体力活动的状态。",["Berjalan pantas setiap petang membantu meningkatkan kecergasan."],["kesihatan"]),
    makeEntry("regangan","regangan","kata nama","Pergerakan yang memanjangkan otot untuk menyediakan tubuh atau mengurangkan ketegangan.","Stretching; movements that lengthen muscles to prepare the body or ease tension.","伸展；拉长肌肉以准备身体活动或缓解紧绷的动作。",["Lakukan regangan ringan sebelum mula berlari."],["kesihatan"]),
    makeEntry("otot","otot","kata nama","Tisu badan yang mengecut dan mengendur untuk menghasilkan pergerakan.","Muscle; body tissue that contracts and relaxes to produce movement.","肌肉；通过收缩和放松产生动作的身体组织。",["Otot kaki terasa lenguh selepas mendaki bukit."],["kesihatan"]),
    makeEntry("sendi","sendi","kata nama","Tempat pertemuan antara tulang yang membolehkan pergerakan.","Joint; the place where bones meet and allow movement.","关节；骨骼相接并允许活动的部位。",["Senaman yang sesuai membantu mengekalkan kelenturan sendi."],["kesihatan"]),
    makeEntry("kulit","kulit","kata nama","Lapisan luar yang melindungi tubuh manusia dan haiwan.","Skin; the outer layer that protects the bodies of people and animals.","皮肤；保护人和动物身体的外层。",["Gunakan pelindung matahari untuk menjaga kulit ketika berada di luar."],["kesihatan"]),
    makeEntry("rambut","rambut","kata nama","Bulu halus yang tumbuh pada kulit kepala atau bahagian tubuh tertentu.","Hair; fine strands growing on the scalp or certain body areas.","头发；生长在头皮或身体某些部位的细丝状毛发。",["Dia mengikat rambut sebelum mula memasak."],["anggota badan"]),
    makeEntry("kening","kening","kata nama","Barisan bulu yang tumbuh di atas setiap mata.","Eyebrow; the strip of hair growing above each eye.","眉毛；生长在每只眼睛上方的一排毛发。",["Dia mengangkat kening apabila mendengar berita itu."],["anggota badan"]),
    makeEntry("dagu","dagu","kata nama","Bahagian bawah muka yang terletak di bawah mulut.","Chin; the lower part of the face beneath the mouth.","下巴；位于嘴巴下方的脸部区域。",["Tali topeng itu terasa ketat di bawah dagu."],["anggota badan"]),
    makeEntry("bahu","bahu","kata nama","Bahagian tubuh yang menghubungkan lengan dengan badan.","Shoulder; the part of the body joining the arm to the torso.","肩膀；连接手臂与躯干的身体部位。",["Beg yang terlalu berat menyebabkan bahu saya sakit."],["anggota badan"]),
    makeEntry("siku","siku","kata nama","Sendi yang menghubungkan bahagian atas dengan bahagian bawah lengan.","Elbow; the joint connecting the upper and lower arm.","肘部；连接上臂与前臂的关节。",["Bengkokkan siku ketika mengangkat beban ringan."],["anggota badan"]),
    makeEntry("pergelangan-tangan","pergelangan tangan","kata nama","Sendi yang menghubungkan tangan dengan lengan bawah.","Wrist; the joint connecting the hand to the forearm.","手腕；连接手与前臂的关节部位。",["Saya memakai jam pada pergelangan tangan kiri."],["anggota badan"]),
    makeEntry("tapak-tangan","tapak tangan","kata nama","Permukaan bahagian dalam tangan yang digunakan untuk memegang atau menyentuh sesuatu.","Palm; the inner surface of the hand used for holding or touching things.","手掌；用于握持或触摸物体的手部内侧表面。",["Dia meletakkan syiling di atas tapak tangan."],["anggota badan"]),
    makeEntry("tumit","tumit","kata nama","Bahagian belakang kaki yang terletak di bawah buku lali.","Heel; the back part of the foot below the ankle.","脚跟；位于脚踝下方的脚部后侧。",["Dia mengalami lepuh pada tumit selepas berjalan jauh."],["anggota badan"]),
    makeEntry("betis","betis","kata nama","Bahagian belakang kaki bawah antara lutut dengan buku lali.","Calf; the back part of the lower leg between knee and ankle.","小腿肚；位于膝盖与脚踝之间的小腿后侧。",["Otot betisnya kejang selepas berlari."],["anggota badan"]),
    makeEntry("lutut","lutut","kata nama","Sendi yang menghubungkan paha dengan bahagian bawah kaki.","Knee; the joint connecting the thigh to the lower leg.","膝盖；连接大腿与小腿的关节。",["Lutut kanan saya sakit apabila menaiki tangga."],["anggota badan"]),
    makeEntry("pinggang","pinggang","kata nama","Bahagian tubuh di antara dada dengan pinggul.","Waist; the part of the body between the chest and hips.","腰部；位于胸部与臀部之间的身体部位。",["Tali pinggang itu terlalu ketat pada pinggangnya."],["anggota badan"]),
    makeEntry("paru-paru","paru-paru","kata nama","Organ pernafasan yang mengambil oksigen dan mengeluarkan karbon dioksida.","Lungs; respiratory organs that take in oxygen and release carbon dioxide.","肺；吸收氧气并排出二氧化碳的呼吸器官。",["Asap rokok boleh menjejaskan kesihatan paru-paru."],["kesihatan"]),
    makeEntry("jantung","jantung","kata nama","Organ berotot yang mengepam darah ke seluruh tubuh.","Heart; a muscular organ that pumps blood throughout the body.","心脏；将血液泵送到全身的肌肉器官。",["Aktiviti fizikal sederhana baik untuk kesihatan jantung."],["kesihatan"]),
    makeEntry("demam","demam","kata nama","Keadaan suhu badan meningkat melebihi paras biasa, lazimnya akibat penyakit.","Fever; a rise in body temperature, often associated with illness.","发烧；体温升高至正常水平以上，通常与疾病有关。",["Anaknya demam sejak malam tadi."],["kesihatan"]),
    makeEntry("batuk","batuk","kata nama","Tindakan mengeluarkan udara dari saluran pernafasan secara tiba-tiba dan kuat.","Cough; a sudden, forceful expulsion of air from the respiratory tract.","咳嗽；从呼吸道突然用力排出空气的动作。",["Tutup mulut ketika batuk untuk mengurangkan penyebaran titisan."],["kesihatan"]),
    makeEntry("selesema","selesema","kata nama","Jangkitan saluran pernafasan yang lazimnya menyebabkan hidung berair dan bersin.","Common cold; a respiratory infection often causing a runny nose and sneezing.","感冒；常引起流鼻涕和打喷嚏的呼吸道感染。",["Saya tidak hadir ke kelas kerana selesema."],["kesihatan"]),
    makeEntry("alahan","alahan","kata nama","Tindak balas sistem imun yang berlebihan terhadap bahan tertentu yang biasanya tidak berbahaya.","Allergy; an excessive immune response to a substance that is usually harmless.","过敏；免疫系统对通常无害物质产生的过度反应。",["Dia mempunyai alahan terhadap kacang tanah."],["kesihatan"]),
    makeEntry("rawatan","rawatan","kata nama","Usaha atau kaedah yang digunakan untuk menjaga atau memulihkan keadaan seseorang yang sakit atau cedera.","Treatment; care or methods used to improve an illness or injury.","治疗；用于照护或改善疾病与伤势的方法。",["Pesakit menerima rawatan susulan di klinik daerah."],["kesihatan"]),
    makeEntry("farmasi","farmasi","kata nama","Tempat ubat dibekalkan atau dijual oleh ahli farmasi bertauliah.","Pharmacy; a place where medicines are supplied or sold by qualified pharmacists.","药房；由合格药剂师供应或销售药物的场所。",["Saya mengambil ubat preskripsi di farmasi hospital."],["kesihatan"]),
    makeEntry("pesakit","pesakit","kata nama","Orang yang menerima pemeriksaan, rawatan atau penjagaan kesihatan.","Patient; a person receiving medical examination, treatment or care.","病人；接受医疗检查、治疗或护理的人。",["Pesakit diminta menunggu di ruang yang disediakan."],["kesihatan"]),
    makeEntry("pertolongan-cemas","pertolongan cemas","kata nama","Bantuan awal kepada orang sakit atau cedera sebelum rawatan lanjut diperoleh.","First aid; immediate assistance given to an ill or injured person before further treatment.","急救；在获得进一步治疗前向病患或伤者提供的初步援助。",["Guru memberikan pertolongan cemas kepada murid yang terjatuh."],["kesihatan"]),
    makeEntry("kecederaan","kecederaan","kata nama","Kerosakan atau luka pada tubuh akibat kemalangan, hentakan atau sebab lain.","Injury; physical harm or damage caused by an accident, impact or other cause.","受伤；因事故、撞击或其他原因造成的身体损伤。",["Pemain itu berehat kerana mengalami kecederaan pada buku lali."],["kesihatan"]),
    makeEntry("luka","luka","kata nama","Kerosakan pada kulit atau tisu badan akibat terpotong, tercalar atau terkena sesuatu.","Wound or cut; damage to skin or body tissue from a cut, scrape or impact.","伤口；皮肤或身体组织因割伤、擦伤或撞击而受损。",["Bersihkan luka kecil itu dengan air bersih."],["kesihatan"]),
    makeEntry("lebam","lebam","kata nama","Perubahan warna pada kulit akibat salur darah kecil pecah selepas hentakan.","Bruise; skin discolouration caused by small blood vessels breaking after impact.","瘀青；受到撞击后小血管破裂导致的皮肤变色。",["Terdapat lebam pada lututnya selepas terjatuh."],["kesihatan"]),
    makeEntry("rehat","rehat","kata nama","Tempoh berhenti daripada bekerja atau melakukan aktiviti untuk memulihkan tenaga.","Rest or break; a period away from work or activity to recover energy.","休息；暂停工作或活动以恢复精力的一段时间。",["Ambil rehat seketika selepas menyiapkan dua bab tugasan."],["kesihatan"]),
    makeEntry("resipi","resipi","kata nama","Senarai bahan dan langkah untuk menyediakan sesuatu makanan atau minuman.","Recipe; a list of ingredients and steps for preparing food or drink.","食谱；准备某种食物或饮料所需的材料和步骤清单。",["Saya mengikuti resipi nenek untuk membuat kuih."],["makanan"]),
    makeEntry("bahan-mentah","bahan mentah","kata nama","Bahan asas yang belum diproses untuk digunakan dalam pembuatan atau penyediaan sesuatu.","Raw material; a basic material not yet processed for production or preparation.","原材料；尚未加工、用于制造或准备某物的基础材料。",["Kilang itu mendapatkan bahan mentah daripada pembekal tempatan."],["perniagaan"]),
    makeEntry("tepung","tepung","kata nama","Serbuk halus daripada bijirin atau bahan lain yang digunakan dalam masakan.","Flour; a fine powder made from grain or other materials and used in cooking.","面粉；由谷物或其他材料制成、用于烹饪的细粉。",["Masukkan tepung sedikit demi sedikit ke dalam adunan."],["makanan"]),
    makeEntry("madu","madu","kata nama","Cecair manis yang dihasilkan oleh lebah daripada nektar bunga.","Honey; a sweet liquid produced by bees from flower nectar.","蜂蜜；蜜蜂利用花蜜酿成的甜味液体。",["Dia menambah sesudu madu ke dalam air suam."],["makanan"]),
    makeEntry("cuka","cuka","kata nama","Cecair berasa masam yang mengandungi asid asetik dan digunakan dalam masakan atau pengawetan.","Vinegar; a sour liquid containing acetic acid, used in cooking or preservation.","醋；含有醋酸、用于烹饪或腌制的酸味液体。",["Tambahkan sedikit cuka ke dalam kuah untuk menyeimbangkan rasa."],["makanan"]),
    makeEntry("santan","santan","kata nama","Cecair berlemak yang diperoleh daripada isi kelapa yang diparut dan diperah.","Coconut milk; a rich liquid extracted from grated coconut flesh.","椰浆；从磨碎并挤压的椰肉中提取的浓稠液体。",["Santan menjadikan kuah kari itu lebih berkrim."],["makanan"]),
    makeEntry("kicap","kicap","kata nama","Sos berwarna gelap yang diperbuat daripada kacang soya yang diperam.","Soy sauce; a dark sauce made from fermented soybeans.","酱油；由发酵大豆制成的深色酱汁。",["Dia menambah sedikit kicap pada mi goreng."],["makanan"]),
    makeEntry("sayur-sayuran","sayur-sayuran","kata nama","Tumbuhan atau bahagian tumbuhan yang dimakan sebagai makanan.","Vegetables; plants or plant parts eaten as food.","蔬菜；作为食物食用的植物或植物部分。",["Ibu menambah sayur-sayuran ke dalam sup ayam."],["makanan"]),
    makeEntry("buah-buahan","buah-buahan","kata nama","Buah daripada tumbuhan yang lazimnya dimakan sebagai makanan.","Fruits; plant produce commonly eaten as food.","水果；通常作为食物食用的植物果实。",["Kanak-kanak digalakkan makan buah-buahan setiap hari."],["makanan"]),
    makeEntry("bijirin","bijirin","kata nama","Biji tanaman seperti padi, gandum dan jagung yang digunakan sebagai makanan.","Cereal grains; seeds of crops such as rice, wheat and maize used as food.","谷物；稻米、小麦和玉米等作物的种子。",["Bijirin penuh membekalkan serat dalam pemakanan harian."],["makanan"]),
    makeEntry("udang","udang","kata nama","Haiwan air bercangkerang yang mempunyai badan memanjang dan kaki kecil.","Prawn or shrimp; an aquatic crustacean with an elongated body and small legs.","虾；身体细长、具有外壳和小足的水生甲壳动物。",["Udang dibersihkan sebelum dimasukkan ke dalam kari."],["makanan"]),
    makeEntry("sotong","sotong","kata nama","Haiwan laut bertubuh lembut dengan sesungut yang digunakan sebagai makanan.","Squid; a soft-bodied sea animal with tentacles, eaten as food.","鱿鱼；具有触腕、可供食用的软体海洋动物。",["Sotong goreng tepung dihidangkan bersama sos cili."],["makanan"]),
    makeEntry("keju","keju","kata nama","Makanan daripada susu yang diproses melalui penggumpalan dan pematangan.","Cheese; a food made by curdling and processing milk.","奶酪；通过凝乳和加工牛奶制成的食品。",["Keju parut ditaburkan di atas piza sebelum dibakar."],["makanan"]),
    makeEntry("mentega","mentega","kata nama","Lemak makanan yang diperbuat daripada krim susu dan digunakan dalam masakan atau sapuan.","Butter; an edible fat made from milk cream, used in cooking or as a spread.","黄油；由奶油制成、用于烹饪或涂抹的食用脂肪。",["Sapukan sedikit mentega pada roti bakar."],["makanan"]),
    makeEntry("yogurt","yogurt","kata nama","Makanan lembut yang dihasilkan melalui penapaian susu menggunakan kultur bakteria.","Yoghurt; a soft food produced by fermenting milk with bacterial cultures.","酸奶；利用细菌培养物发酵牛奶制成的柔软食品。",["Saya makan yogurt bersama potongan buah sebagai sarapan."],["makanan"]),
    makeEntry("jus","jus","kata nama","Cecair yang diperoleh daripada buah atau sayur yang diperah atau diproses.","Juice; liquid extracted from pressed or processed fruit or vegetables.","果汁；从压榨或加工的水果或蔬菜中提取的液体。",["Jus oren itu dibuat daripada buah yang baru diperah."],["makanan"]),
    makeEntry("bekas-makanan","bekas makanan","kata nama","Bekas yang digunakan untuk menyimpan atau membawa makanan.","Food container; a container used to store or carry food.","饭盒；用于储存或携带食物的容器。",["Basuh bekas makanan selepas digunakan."],["rumah"]),
    makeEntry("tudung-saji","tudung saji","kata nama","Penutup yang diletakkan di atas makanan untuk melindunginya daripada serangga dan habuk.","Food cover; a cover placed over food to protect it from insects and dust.","食物罩；盖在食物上以防昆虫和灰尘的罩子。",["Nenek menutup lauk dengan tudung saji."],["rumah"]),
    makeEntry("peti-beku","peti beku","kata nama","Ruang atau peralatan yang mengekalkan suhu sangat rendah untuk membekukan makanan.","Freezer; a compartment or appliance that keeps food at very low temperatures.","冷冻柜；以极低温度冷冻食物的空间或设备。",["Ikan itu disimpan di dalam peti beku."],["rumah"]),
    makeEntry("pendingin-hawa","pendingin hawa","kata nama","Peralatan yang mengawal suhu dan kelembapan udara di dalam ruang tertutup.","Air conditioner; an appliance that controls indoor air temperature and humidity.","空调；调节封闭空间内空气温度和湿度的设备。",["Tutup tingkap ketika pendingin hawa sedang digunakan."],["rumah"]),
    makeEntry("suis","suis","kata nama","Alat yang digunakan untuk menyambung atau memutuskan aliran elektrik dalam litar.","Switch; a device used to connect or disconnect electrical flow in a circuit.","开关；用于接通或切断电路电流的装置。",["Jangan sentuh suis elektrik dengan tangan yang basah."],["rumah"]),
    makeEntry("soket","soket","kata nama","Punca sambungan elektrik yang menerima palam sesuatu peralatan.","Socket; an electrical outlet that accepts an appliance plug.","插座；供电器插头接入的电源接口。",["Soket di dinding itu longgar dan perlu dibaiki."],["rumah"]),
    makeEntry("palam","palam","kata nama","Bahagian pada hujung kabel yang dimasukkan ke dalam soket untuk menyambungkan peralatan kepada bekalan elektrik.","Plug; the part at the end of a cable inserted into a socket.","插头；电缆末端插入插座以连接电器的部件。",["Cabut palam selepas selesai menggunakan seterika."],["rumah"]),
    makeEntry("kabel","kabel","kata nama","Wayar atau himpunan wayar yang digunakan untuk menghantar elektrik atau isyarat.","Cable; a wire or group of wires used to carry electricity or signals.","电缆；用于传输电力或信号的电线或线束。",["Jauhkan kabel daripada laluan berjalan supaya orang tidak tersadung."],["teknologi"]),
    makeEntry("pengecas","pengecas","kata nama","Peranti yang membekalkan tenaga elektrik kepada bateri sesuatu alat.","Charger; a device that supplies electrical energy to a device's battery.","充电器；向设备电池提供电能的装置。",["Saya tertinggal pengecas telefon di rumah."],["teknologi"]),
    makeEntry("bateri","bateri","kata nama","Peranti yang menyimpan tenaga kimia dan membekalkan tenaga elektrik.","Battery; a device that stores chemical energy and supplies electrical power.","电池；储存化学能并提供电能的装置。",["Bateri alat kawalan jauh perlu diganti."],["teknologi"]),
    makeEntry("kamera","kamera","kata nama","Peranti yang digunakan untuk merakam gambar atau video.","Camera; a device used to capture photographs or video.","相机；用于拍摄照片或视频的设备。",["Dia menggunakan kamera telefon untuk mengambil gambar pemandangan."],["teknologi"]),
    makeEntry("gambar-rajah","gambar rajah","kata nama","Lukisan yang menerangkan susunan, hubungan atau proses sesuatu perkara.","Diagram; a drawing explaining the arrangement, relationships or process of something.","示意图；说明某事物结构、关系或过程的图形。",["Gambar rajah itu menunjukkan aliran air dalam sistem paip."],["pendidikan"]),
    makeEntry("utara","utara","kata nama","Arah mata angin yang bertentangan dengan selatan.","North; the cardinal direction opposite south.","北方；与南方相对的基本方位。",["Kawasan pergunungan terletak di utara negeri itu."],["alam"]),
    makeEntry("selatan","selatan","kata nama","Arah mata angin yang bertentangan dengan utara.","South; the cardinal direction opposite north.","南方；与北方相对的基本方位。",["Mereka berpindah ke selatan Semenanjung Malaysia."],["alam"]),
    makeEntry("timur","timur","kata nama","Arah mata angin tempat matahari terbit secara umum.","East; the cardinal direction in which the sun generally rises.","东方；太阳通常升起的基本方位。",["Matahari terbit dari arah timur."],["alam"]),
    makeEntry("barat","barat","kata nama","Arah mata angin tempat matahari terbenam secara umum.","West; the cardinal direction in which the sun generally sets.","西方；太阳通常落下的基本方位。",["Langit di sebelah barat bertukar jingga ketika senja."],["alam"]),
    makeEntry("pesisir","pesisir","kata nama","Kawasan daratan yang terletak di sepanjang tepi laut atau pantai.","Coast or shoreline; land along the edge of the sea.","海岸；沿着海边或海滩延伸的陆地区域。",["Kampung nelayan itu terletak di pesisir pantai."],["alam"]),
    makeEntry("muara","muara","kata nama","Tempat sungai mengalir masuk ke laut, tasik atau sungai yang lebih besar.","River mouth or estuary; where a river flows into the sea, lake or larger river.","河口；河流流入海洋、湖泊或较大河流的地方。",["Bot nelayan berlabuh berhampiran muara sungai."],["alam"]),
    makeEntry("teluk","teluk","kata nama","Bahagian laut yang menjorok ke daratan dan dikelilingi daratan pada beberapa sisinya.","Bay; a part of the sea extending into land and partly enclosed by it.","海湾；向陆地凹入并部分被陆地环绕的海域。",["Perkampungan itu menghadap sebuah teluk yang terlindung."],["alam"]),
    makeEntry("selat","selat","kata nama","Laluan air sempit yang menghubungkan dua kawasan laut dan memisahkan daratan.","Strait; a narrow waterway connecting two seas and separating land masses.","海峡；连接两个海域并分隔陆地的狭窄水道。",["Kapal dagang melalui Selat Melaka setiap hari."],["alam"]),
    makeEntry("tasik","tasik","kata nama","Kawasan air yang luas dan dikelilingi daratan.","Lake; a large body of water surrounded by land.","湖泊；被陆地环绕的大片水域。",["Penduduk berjoging di sekitar tasik pada waktu pagi."],["alam"]),
    makeEntry("paya","paya","kata nama","Kawasan tanah rendah yang kerap digenangi air dan ditumbuhi tumbuhan tertentu.","Swamp or marsh; low-lying land frequently covered with water and vegetation.","沼泽；经常被水淹没并长有特定植物的低洼地。",["Burung air mencari makanan di kawasan paya."],["alam"]),
    makeEntry("hutan-bakau","hutan bakau","kata nama","Hutan pesisir berlumpur yang didominasi pokok bakau tahan air masin.","Mangrove forest; a coastal muddy forest dominated by salt-tolerant mangroves.","红树林；以耐盐红树植物为主的沿海泥滩森林。",["Hutan bakau menjadi tempat pembiakan pelbagai hidupan laut."],["alam"]),
    makeEntry("air-terjun","air terjun","kata nama","Aliran air sungai yang jatuh dari tempat tinggi ke kawasan lebih rendah.","Waterfall; river water falling from a height to a lower area.","瀑布；河水从高处流向较低处形成的水流。",["Laluan ke air terjun itu licin selepas hujan."],["alam"]),
    makeEntry("mata-air","mata air","kata nama","Tempat air bawah tanah keluar secara semula jadi ke permukaan bumi.","Spring; a place where groundwater naturally emerges at the surface.","泉眼；地下水自然涌出地表的地方。",["Mata air itu mengalir sepanjang tahun."],["alam"]),
    makeEntry("anak-sungai","anak sungai","kata nama","Sungai kecil yang mengalir masuk ke sungai yang lebih besar.","Tributary or stream; a small river flowing into a larger river.","支流；流入较大河流的小河。",["Anak sungai itu menjadi cetek ketika musim kemarau."],["alam"]),
    makeEntry("banjir-kilat","banjir kilat","kata nama","Banjir yang berlaku dengan cepat selepas hujan lebat atau limpahan air mendadak.","Flash flood; flooding that occurs rapidly after heavy rain or sudden overflow.","突发洪水；暴雨或水位突然溢出后迅速发生的洪水。",["Banjir kilat menyebabkan beberapa jalan di bandar itu ditutup."],["alam"]),
    makeEntry("kemarau","kemarau","kata nama","Tempoh panjang dengan hujan sangat sedikit sehingga menyebabkan kekurangan air.","Drought; a prolonged period of little rainfall causing water shortages.","旱灾；长期降雨稀少并导致缺水的时期。",["Petani menghadapi kesukaran ketika musim kemarau berpanjangan."],["alam"]),
    makeEntry("petir","petir","kata nama","Cahaya kilat yang disertai bunyi guruh akibat nyahcas elektrik di atmosfera.","Lightning; a flash of light caused by an electrical discharge in the atmosphere.","闪电；大气放电现象产生的强光，通常伴随雷声。",["Jangan berlindung di bawah pokok tinggi semasa petir."],["alam"]),
    makeEntry("guruh","guruh","kata nama","Bunyi kuat yang terhasil daripada pengembangan udara akibat kilat.","Thunder; the loud sound caused by air expanding after lightning.","雷声；闪电后空气膨胀所产生的巨大声响。",["Bunyi guruh kedengaran dari jauh sebelum hujan turun."],["alam"]),
    makeEntry("pelangi","pelangi","kata nama","Lengkungan warna di langit yang terbentuk apabila cahaya matahari berinteraksi dengan titisan air.","Rainbow; an arc of colours formed when sunlight interacts with water droplets.","彩虹；阳光与水滴相互作用后在天空形成的彩色弧线。",["Pelangi muncul selepas hujan berhenti."],["alam"]),
    makeEntry("embun","embun","kata nama","Titisan air halus yang terbentuk pada permukaan sejuk apabila wap air memeluwap.","Dew; tiny water droplets formed on cool surfaces by condensation.","露水；水汽凝结后在较冷表面形成的细小水滴。",["Embun pagi masih kelihatan pada daun rumput."],["alam"]),
    makeEntry("kabut","kabut","kata nama","Titisan air halus yang terapung dekat permukaan bumi dan mengurangkan jarak penglihatan.","Fog or mist; tiny water droplets near the ground that reduce visibility.","雾；接近地面的细小水滴群，会降低能见度。",["Kabut tebal menyelubungi jalan di kawasan tanah tinggi."],["alam"]),
    makeEntry("kelembapan","kelembapan","kata nama","Kandungan wap air dalam udara atau sesuatu bahan.","Humidity or moisture; the amount of water vapour in air or a material.","湿度；空气或材料中的水汽含量。",["Kelembapan udara meningkat selepas hujan petang."],["alam"]),
    makeEntry("suhu","suhu","kata nama","Ukuran darjah kepanasan atau kesejukan sesuatu benda atau persekitaran.","Temperature; a measure of how hot or cold something is.","温度；衡量物体或环境冷热程度的数值。",["Periksa suhu badan jika anak kelihatan tidak sihat."],["sains"]),
    makeEntry("ramalan-cuaca","ramalan cuaca","kata nama","Anggaran keadaan atmosfera bagi sesuatu kawasan dalam tempoh tertentu.","Weather forecast; an estimate of atmospheric conditions for an area over a period.","天气预报；对某地区特定时段大气状况的预测。",["Semak ramalan cuaca sebelum merancang aktiviti luar."],["alam"]),
    makeEntry("musim-tengkujuh","musim tengkujuh","kata nama","Tempoh yang lazimnya menerima hujan lebat dan berterusan di kawasan tertentu.","Monsoon season; a period with prolonged heavy rain in certain regions.","季风雨季；某些地区持续出现强降雨的时期。",["Penduduk pesisir bersedia menghadapi musim tengkujuh."],["alam"]),
    makeEntry("hakisan","hakisan","kata nama","Proses pengikisan tanah atau batuan oleh air, angin atau tindakan lain.","Erosion; the wearing away of soil or rock by water, wind or other forces.","侵蚀；水、风或其他作用逐渐磨损土壤或岩石的过程。",["Penanaman pokok membantu mengurangkan hakisan tanah."],["alam"]),
    makeEntry("tanah-runtuh","tanah runtuh","kata nama","Pergerakan tanah, batu atau bahan cerun menuruni kawasan tinggi.","Landslide; movement of soil, rock or slope material downhill.","山体滑坡；土壤、岩石或坡面物质向下移动的现象。",["Tanah runtuh menutup jalan menuju ke kampung itu."],["alam"]),
    makeEntry("sisa","sisa","kata nama","Baki bahan yang tertinggal selepas sesuatu digunakan, diproses atau dihasilkan.","Residue or waste; material left after use, processing or production.","残余物；使用、加工或生产后留下的材料。",["Sisa makanan diasingkan daripada bahan kitar semula."],["alam"]),
    makeEntry("sisa-makanan","sisa makanan","kata nama","Makanan yang tidak dimakan atau lebihan daripada proses penyediaan makanan.","Food waste; uneaten food or leftovers from food preparation.","食物残渣；未吃完的食物或备餐过程中产生的剩余物。",["Ambil makanan mengikut keperluan supaya sisa makanan dapat dikurangkan."],["alam"]),
    makeEntry("tong-kitar-semula","tong kitar semula","kata nama","Bekas khas untuk mengumpulkan bahan yang boleh dikitar semula.","Recycling bin; a designated container for collecting recyclable materials.","回收桶；专门收集可回收材料的容器。",["Masukkan botol plastik ke dalam tong kitar semula yang betul."],["alam"]),
    makeEntry("pusat-kitar-semula","pusat kitar semula","kata nama","Tempat bahan terpakai dikumpulkan, diasingkan dan diproses untuk dikitar semula.","Recycling centre; a place where used materials are collected, sorted and processed.","回收中心；收集、分类和处理可回收旧材料的场所。",["Penduduk menghantar surat khabar lama ke pusat kitar semula."],["alam"]),
    makeEntry("tapak-pelupusan","tapak pelupusan","kata nama","Kawasan yang ditetapkan untuk menempatkan sisa buangan secara terkawal.","Disposal site or landfill; an area designated for controlled waste disposal.","废弃物处置场；指定用于受控处理废弃物的区域。",["Sisa pepejal dihantar ke tapak pelupusan yang diluluskan."],["alam"]),
    makeEntry("sukarelawan","sukarelawan","kata nama","Orang yang menawarkan tenaga atau khidmat secara rela tanpa paksaan.","Volunteer; a person who willingly offers time or service.","志愿者；自愿提供时间或服务的人。",["Sukarelawan membantu mengagihkan makanan kepada mangsa banjir."],["masyarakat"]),
    makeEntry("derma","derma","kata nama","Sumbangan wang, barang atau bantuan yang diberikan untuk tujuan tertentu.","Donation; money, goods or assistance given for a particular purpose.","捐赠；为特定目的提供的钱财、物品或援助。",["Orang ramai menghulurkan derma kepada keluarga yang kehilangan rumah."],["masyarakat"]),
    makeEntry("sumbangan","sumbangan","kata nama","Pemberian atau usaha yang membantu menjayakan sesuatu tujuan.","Contribution; a gift or effort that helps achieve a purpose.","贡献；有助于达成目标的捐助或努力。",["Sumbangan penduduk membolehkan dewan komuniti dibaiki."],["masyarakat"]),
    makeEntry("kebajikan","kebajikan","kata nama","Keadaan hidup yang baik serta usaha menjaga keperluan dan kepentingan masyarakat.","Welfare; well-being and efforts to protect people's needs and interests.","福利；良好的生活状况，以及保障个人或社会需求与利益的工作。",["Program kebajikan membantu keluarga berpendapatan rendah."],["masyarakat"]),
    makeEntry("penduduk","penduduk","kata nama","Orang yang tinggal secara tetap atau untuk suatu tempoh di sesuatu kawasan.","Residents; people living permanently or for a period in an area.","居民；长期或暂时居住在某个地区的人。",["Penduduk kampung mengadakan gotong-royong pada hujung minggu."],["masyarakat"]),
    makeEntry("komuniti","komuniti","kata nama","Kumpulan orang yang tinggal di kawasan sama atau mempunyai kepentingan bersama.","Community; a group of people living in the same area or sharing interests.","社区；居住在同一地区或拥有共同利益的一群人。",["Komuniti itu bekerjasama membersihkan taman permainan."],["masyarakat"]),
    makeEntry("persatuan","persatuan","kata nama","Organisasi yang dibentuk oleh sekumpulan orang untuk tujuan atau kepentingan bersama.","Association; an organisation formed by people for a shared purpose or interest.","协会；为共同目标或利益而成立的组织。",["Dia menyertai persatuan fotografi di kolej."],["masyarakat"]),
    makeEntry("jawatankuasa","jawatankuasa","kata nama","Kumpulan orang yang dilantik untuk mengurus atau membuat keputusan tentang sesuatu perkara.","Committee; a group appointed to manage or decide on a matter.","委员会；受委任处理或决定某事项的一组人员。",["Jawatankuasa program membahagikan tugas kepada setiap ahli."],["pentadbiran"]),
    makeEntry("pengerusi","pengerusi","kata nama","Orang yang mengetuai mesyuarat atau sesebuah jawatankuasa.","Chairperson; a person who leads a meeting or committee.","主席；主持会议或领导委员会事务的人。",["Pengerusi meminta semua ahli memberikan pandangan."],["pentadbiran"]),
    makeEntry("setiausaha","setiausaha","kata nama","Orang yang mengurus rekod, surat-menyurat dan urusan pentadbiran organisasi.","Secretary; a person managing records, correspondence and administrative matters.","秘书；负责组织记录、通信和行政事务的人。",["Setiausaha mencatat keputusan yang dibuat dalam mesyuarat."],["pentadbiran"]),
    makeEntry("bendahari","bendahari","kata nama","Orang yang bertanggungjawab mengurus wang dan rekod kewangan organisasi.","Treasurer; a person responsible for an organisation's money and financial records.","财务；负责管理组织资金和财务记录的人。",["Bendahari membentangkan laporan kewangan pada akhir tahun."],["pentadbiran"]),
    makeEntry("keahlian","keahlian","kata nama","Status atau keadaan seseorang sebagai anggota sesuatu kumpulan atau organisasi.","Membership; the status of belonging to a group or organisation.","会员资格；某人作为团体或组织成员的身份或状态。",["Keahlian perpustakaan itu terbuka kepada semua penduduk."],["masyarakat"]),
    makeEntry("berkala","berkala","kata adjektif","Berlaku atau dilakukan pada selang masa yang tetap atau tertentu.","Periodic or regular; occurring at fixed or specified intervals.","定期的；按固定或特定时间间隔发生或进行的。",["Pemeriksaan berkala membantu mengesan kerosakan lebih awal."],["masa"]),
    makeEntry("sementara","sementara","kata adjektif","Berlaku atau digunakan untuk tempoh terhad dan bukan kekal.","Temporary; lasting or used for a limited period, not permanent.","临时的；在有限期间内存在或使用，并非永久的。",["Pejabat sementara dibuka berhampiran tapak pembinaan."],["masa"]),
    makeEntry("kekal","kekal","kata adjektif","Berterusan atau tidak berubah dan tidak bersifat sementara.","Permanent or lasting; continuing without being temporary.","永久的；持续存在或不变，并非暂时的。",["Warna itu kekal walaupun kain dibasuh berkali-kali."],["sifat"]),
    makeEntry("terkini","terkini","kata adjektif","Paling baharu atau mengandungi maklumat yang paling mutakhir.","Latest or current; most recent or containing up-to-date information.","最新的；最新近或包含当前信息的。",["Pastikan aplikasi menggunakan versi terkini."],["masa"]),
    makeEntry("terdahulu","terdahulu","kata adjektif","Berlaku atau wujud sebelum masa atau perkara yang sedang dibincangkan.","Previous or earlier; occurring before the matter being discussed.","先前的；发生或存在于当前讨论事项之前的。",["Sila rujuk laporan terdahulu untuk melihat perubahan."],["masa"]),
    makeEntry("serentak","serentak","kata adverba","Pada masa yang sama.","Simultaneously; at the same time.","同时；在同一时间。",["Dua kelas memulakan ujian secara serentak."],["masa"]),
    makeEntry("beransur-ansur","beransur-ansur","kata adverba","Sedikit demi sedikit dalam tempoh tertentu.","Gradually; little by little over a period.","逐渐地；在一段时间内一点一点地。",["Air sungai surut beransur-ansur selepas hujan berhenti."],["masa"]),
    makeEntry("sepenuhnya","sepenuhnya","kata adverba","Dengan lengkap atau meliputi semua bahagian tanpa kekurangan.","Fully or completely; covering all parts without omission.","完全地；完整涵盖所有部分，没有遗漏。",["Pastikan borang diisi sepenuhnya sebelum dihantar."],["cara"]),
    makeEntry("sekurang-kurangnya","sekurang-kurangnya","kata adverba","Pada kadar atau jumlah minimum yang dinyatakan.","At least; to the minimum stated amount or degree.","至少；达到所说明的最低数量或程度。",["Setiap kumpulan perlu menyediakan sekurang-kurangnya tiga contoh."],["kuantiti"]),
    makeEntry("terutamanya","terutamanya","kata adverba","Lebih-lebih lagi atau secara khusus berkenaan perkara yang paling penting.","Especially or particularly; with emphasis on the most important matter.","尤其；特别是；着重指出最重要的事项。",["Kawasan itu sesak terutamanya pada waktu puncak."],["kata fungsi"]),
    makeEntry("walaupun","walaupun","kata hubung","Menghubungkan klausa yang menunjukkan keadaan berlawanan atau tidak menghalang sesuatu berlaku.","Although or even though; connects clauses expressing contrast.","虽然；尽管；连接表示转折的分句。",["Walaupun hujan lebat, perlawanan diteruskan selepas pemeriksaan padang."],["kata fungsi"]),
    makeEntry("manakala","manakala","kata hubung","Menghubungkan dua perkara untuk menunjukkan perbezaan atau kejadian serentak.","Whereas or while; connects matters to show contrast or simultaneous events.","而；与此同时；连接事项以表示对比或同时发生。",["Ali memilih teh, manakala adiknya memesan kopi."],["kata fungsi"]),
    makeEntry("sekiranya","sekiranya","kata hubung","Jika atau apabila sesuatu syarat atau keadaan berlaku.","If or in the event that; introduces a condition.","如果；倘若；引出条件或情况。",["Sekiranya anda lewat, sila maklumkan kepada penyelia."],["kata fungsi"]),
    makeEntry("melainkan","melainkan","kata hubung","Kecuali jika atau selain daripada keadaan yang dinyatakan.","Unless or except; introduces an exception or condition.","除非；除了；引出例外或条件。",["Semua peserta perlu hadir melainkan mendapat kebenaran bertulis."],["kata fungsi"]),
    makeEntry("selain-itu","selain itu","kata adverba","Digunakan untuk menambah maklumat atau perkara lain kepada sesuatu pernyataan.","Besides or furthermore; used to add further information.","此外；除此之外；用于补充其他信息或事项。",["Selain itu, peserta perlu membawa alat tulis sendiri."],["kata fungsi"]),
    makeEntry("contohnya","contohnya","kata adverba","Digunakan untuk memperkenalkan contoh bagi menjelaskan sesuatu perkara.","For example; used to introduce examples that clarify a point.","例如；用于引出说明某事项的例子。",["Banyak buah tempatan kaya dengan vitamin, contohnya jambu batu dan betik."],["kata fungsi"]),
    makeEntry("sebaliknya","sebaliknya","kata adverba","Digunakan untuk menyatakan keadaan yang berlawanan atau pilihan bertentangan.","Instead or on the contrary; expresses an opposite situation or alternative.","相反；反而；表示相反情况或替代选择。",["Jangan buang botol itu; sebaliknya, masukkannya ke dalam tong kitar semula."],["kata fungsi"])
  );
})();
